-- 세트 344: 텍스트 변환 손에 익히기: tr, cut -d -f, sed s///g·-n·d·-i, sort -t -k, paste, 도구 이어서 새 파일 만들기
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_linux_text_transform_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (344, 1, '글자를 다른 글자로 바꾸기 (tr)', '`/tmp/lab/members.csv` 는 구성원 8명의 명단입니다. 한 줄이 한 명이고 `번호,이름,팀,도시,점수,상태` 순서로 쉼표로 나뉩니다. 모든 **쉼표를 공백 하나로 바꾼** 내용을 새 파일 **`/tmp/lab/members_space.txt`** 에 저장하세요. 원본은 그대로 둡니다.', '`tr 바꿀글자 새글자` 는 입력에서 글자를 하나씩 바꿉니다. `tr` 는 파일 이름을 인자로 받지 않으니 `<` 로 파일을 입력에 넣고, 결과는 `>` 로 새 파일에 보냅니다.', 'tr '','' '' '' < /tmp/lab/members.csv > /tmp/lab/members_space.txt
cat /tmp/lab/members_space.txt

# tr 은 글자 하나를 글자 하나로 바꾼다. 파일은 < 로 넣는다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/members_space.txt | cut -d\\" \\" -f1)\\" = \\"aec1fd840c541d69dc495a66367b9b96\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "쉼표가 모두 공백으로 바뀌어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members_space.txt | cut -d\\" \\" -f1)\\" = \\"aec1fd840c541d69dc495a66367b9b96\\" ]"]}, {"label": "원본 members.csv 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 2, '쉼표로 나뉜 칸 하나 뽑기 (cut -d -f)', '명단에서 **이름**(둘째 칸)만 뽑아 **`/tmp/lab/names.txt`** 에 한 줄에 하나씩 저장하세요. 줄 순서는 명단 그대로입니다.', '`cut` 은 줄을 구분 문자로 나눠 원하는 칸만 꺼냅니다. 구분 문자는 `-d`, 칸 번호는 `-f` 로 줍니다. 칸은 1번부터 셉니다.', 'cut -d, -f2 /tmp/lab/members.csv > /tmp/lab/names.txt
cat /tmp/lab/names.txt

# -d 는 구분 문자, -f 는 꺼낼 칸 번호다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/names.txt | cut -d\\" \\" -f1)\\" = \\"5623eb27e249955b00a06576713273a3\\" ] ) && ( [ \\"$(wc -l < /tmp/lab/names.txt)\\" -eq 8 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이름만 명단 순서대로 들어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/names.txt | cut -d\\" \\" -f1)\\" = \\"5623eb27e249955b00a06576713273a3\\" ]"]}, {"label": "8 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/names.txt)\\" -eq 8 ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 3, '구분 문자 지정하기 (cut -d)', '명단에서 둘째 칸(이름)만 뽑으려고 합니다. 이 파일의 칸은 **어떤 문자**로 나뉘어 있는지 보고, 빈칸에 알맞은 구분 문자를 채우세요.', '`/tmp/lab/members.csv` 를 `head -n 2` 같은 명령으로 열어 보면 칸 사이에 어떤 글자가 있는지 바로 보입니다.', NULL, NULL, '[]', 'fill', '[",", ";", ":", "|"]', NULL, '명단은 `1,kim,dev,Seoul,82,active` 처럼 **쉼표**로 칸이 나뉘므로 `-d'',''` 가 맞습니다. 다른 문자를 주면 줄 안에 그 문자가 없어서 `cut` 이 줄 전체를 그대로 내놓습니다. 그래서 이름만 뽑히지 않습니다.', '[0]', 'cut -d''{0}'' -f2 /tmp/lab/members.csv', NULL, '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 4, 'sed s/// 는 한 줄에서 몇 번 바꿀까?', '한 줄이 `dev,dev,dev` 입니다. 이 줄에 `sed ''s/dev/eng/''` 를 적용하면 어떤 결과가 나올까요?', '`s/찾을것/바꿀것/` 은 기본으로 한 줄 안에서 **처음 찾은 것까지만** 바꿉니다. 끝에 붙이는 `g` 같은 플래그가 있는지 명령을 다시 읽어 보세요.', NULL, NULL, '[]', 'choice', '["`eng,eng,eng` — 줄 안의 것이 전부 바뀐다", "`dev,dev,dev` — 아무것도 바뀌지 않는다", "`eng,dev,eng` — 하나 건너 하나씩 바뀐다", "`eng,dev,dev` — 줄마다 처음 하나만 바뀐다"]', 3, '`s///` 는 플래그가 없으면 각 줄에서 **처음 맞는 것 하나**만 바꿉니다. 그래서 `eng,dev,dev` 가 됩니다. 줄 안의 것을 전부 바꾸려면 `s/dev/eng/g` 처럼 끝에 `g` 를 붙입니다. 보기 중 전부 바뀐다는 쪽은 `g` 가 있을 때의 결과이고, 하나 건너 바뀌는 동작은 sed 에 없으며, 아무것도 안 바뀌는 건 찾는 글자가 줄에 없을 때입니다.', NULL, NULL, NULL, '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 5, '줄 안의 것을 전부 바꾸기 (sed s///g)', '명단의 쉼표 한 개를 **` | `**(공백, 세로선, 공백)로 바꿔서 읽기 쉬운 표 모양으로 만들려고 합니다. 한 줄에 쉼표가 여러 개이므로 **전부** 바꾼 결과를 **`/tmp/lab/members_table.txt`** 에 저장하세요. 예: `1 | kim | dev | Seoul | 82 | active`', '`sed ''s/찾을것/바꿀것/플래그'' 파일` 모양입니다. 한 줄에 여러 개를 모두 바꾸는 플래그가 있습니다. 바꿀 글자에 공백이 들어가니 명령 전체를 작은따옴표로 감싸세요.', 'sed ''s/,/ | /g'' /tmp/lab/members.csv > /tmp/lab/members_table.txt
cat /tmp/lab/members_table.txt

# g 가 없으면 각 줄의 첫 쉼표만 바뀐다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/members_table.txt | cut -d\\" \\" -f1)\\" = \\"84199a013f34cda2ec9abc09df4d7f2a\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "모든 쉼표가 '' | '' 로 바뀌어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members_table.txt | cut -d\\" \\" -f1)\\" = \\"84199a013f34cda2ec9abc09df4d7f2a\\" ]"]}, {"label": "원본 members.csv 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 6, '특정 줄만 출력하기 (sed -n ''Np'')', '명단의 **4번째 줄**만 그대로 **`/tmp/lab/fourth.txt`** 에 저장하세요. 다른 줄은 들어가면 안 됩니다.', '`sed` 는 기본으로 모든 줄을 출력합니다. `-n` 을 주면 자동 출력이 꺼지고, `''줄번호p''` 로 지정한 줄만 출력됩니다.', 'sed -n ''4p'' /tmp/lab/members.csv > /tmp/lab/fourth.txt
cat /tmp/lab/fourth.txt

# -n 이 없으면 4번째 줄이 두 번 나오고 나머지 줄도 모두 나온다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/fourth.txt | cut -d\\" \\" -f1)\\" = \\"72917b5d40241151836c57c735063488\\" ] ) && ( [ \\"$(wc -l < /tmp/lab/fourth.txt)\\" -eq 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "4번째 줄만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/fourth.txt | cut -d\\" \\" -f1)\\" = \\"72917b5d40241151836c57c735063488\\" ]"]}, {"label": "1 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/fourth.txt)\\" -eq 1 ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 7, '패턴이 있는 줄 지우기 (sed ''/패턴/d'')', '상태가 `retired`(퇴직)인 사람은 명단에서 빼려고 합니다. `retired` 가 들어 있는 줄을 **지운 나머지** 줄을 순서 그대로 **`/tmp/lab/active.csv`** 에 저장하세요. 원본은 그대로 둡니다.', '`sed ''/패턴/d''` 는 패턴이 들어 있는 줄을 지우고 나머지를 출력합니다. 결과는 새 파일로 보냅니다.', 'sed ''/retired/d'' /tmp/lab/members.csv > /tmp/lab/active.csv
cat /tmp/lab/active.csv

# /패턴/ 은 줄을 고르는 주소이고 d 는 그 줄을 지우는 명령이다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/active.csv | cut -d\\" \\" -f1)\\" = \\"dff7c03f101f468f8671286495e42993\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "retired 줄만 빠지고 나머지는 순서 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/active.csv | cut -d\\" \\" -f1)\\" = \\"dff7c03f101f468f8671286495e42993\\" ]"]}, {"label": "원본 members.csv 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 8, '파일을 직접 고치기 (sed -i)', '`/tmp/lab/work.csv` 는 명단을 복사해 둔 작업용 파일입니다. 이 파일 안의 도시 **`Seoul` 을 `Daejeon` 으로** 바꾼 상태로 **파일 자체를 고치세요**. 새 파일을 만들지 말고 `work.csv` 를 직접 수정합니다. 원본 `members.csv` 는 그대로여야 합니다.', '`sed` 는 보통 결과를 화면에 보여 줄 뿐 파일은 그대로입니다. 파일 자체를 바꾸는 옵션(`-i`)을 붙이면 제자리에서 수정합니다. 고친 뒤에는 `cat` 으로 확인하세요.', 'sed -i ''s/Seoul/Daejeon/'' /tmp/lab/work.csv
cat /tmp/lab/work.csv

# -i 는 결과를 파일에 다시 써 넣는다. 처음 쓸 때는 cp 로 백업을 떠 두면 안전하다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/work.csv | cut -d\\" \\" -f1)\\" = \\"5d33108e4993aa0bf4a6063fbe4db162\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "work.csv 의 Seoul 이 모두 Daejeon 으로 바뀌어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/work.csv | cut -d\\" \\" -f1)\\" = \\"5d33108e4993aa0bf4a6063fbe4db162\\" ]"]}, {"label": "원본 members.csv 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 9, '열을 기준으로 정렬하기 (sort -t -k)', '명단을 **점수(5번째 칸)가 높은 순서**로 줄 세워 **`/tmp/lab/by_score.csv`** 에 저장하세요. 줄 전체가 그대로 있어야 하고 8줄 모두 들어갑니다. 점수에는 세 자리 숫자도 있으니 숫자 크기로 비교해야 합니다.', '`sort -t 구분문자 -k 칸번호` 로 기준 칸을 정합니다. 숫자 크기로 비교하는 옵션과 큰 것부터 보는 옵션을 함께 주세요. `-k5,5` 처럼 쓰면 5번째 칸 하나만 기준이 됩니다.', 'sort -t, -k5,5nr /tmp/lab/members.csv > /tmp/lab/by_score.csv
cat /tmp/lab/by_score.csv

# -n 이 없으면 100 이 91 보다 작다고 본다 (글자 비교)', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/by_score.csv | cut -d\\" \\" -f1)\\" = \\"90c7d91a1fdb0ae11ebbe7ce04ca6d0f\\" ] ) && ( [ \\"$(wc -l < /tmp/lab/by_score.csv)\\" -eq 8 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "점수 높은 순으로 줄 전체가 정렬되어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/by_score.csv | cut -d\\" \\" -f1)\\" = \\"90c7d91a1fdb0ae11ebbe7ce04ca6d0f\\" ]"]}, {"label": "8 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/by_score.csv)\\" -eq 8 ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 10, '두 파일을 옆으로 붙이기 (paste)', '`/tmp/lab/bonus.txt` 에는 명단과 **같은 순서**로 구성원별 보너스 점수가 한 줄에 하나씩 적혀 있습니다. 명단의 각 줄 **뒤에 쉼표와 보너스를 붙여서** (`1,kim,dev,Seoul,82,active,5` 모양) **`/tmp/lab/members_bonus.csv`** 에 저장하세요.', '`paste 파일1 파일2` 는 두 파일의 같은 번째 줄끼리 옆으로 이어 붙입니다. 기본 구분은 탭이니, 구분 문자를 바꾸는 옵션(`-d`)으로 쉼표를 주세요.', 'paste -d, /tmp/lab/members.csv /tmp/lab/bonus.txt > /tmp/lab/members_bonus.csv
cat /tmp/lab/members_bonus.csv

# 옵션 없이 쓰면 두 줄 사이에 탭이 들어간다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/members_bonus.csv | cut -d\\" \\" -f1)\\" = \\"9abc61cb4afe7d3e859a837cd09978aa\\" ] ) && ( [ \\"$(wc -l < /tmp/lab/members_bonus.csv)\\" -eq 8 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "각 줄 뒤에 쉼표와 보너스가 붙어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members_bonus.csv | cut -d\\" \\" -f1)\\" = \\"9abc61cb4afe7d3e859a837cd09978aa\\" ]"]}, {"label": "8 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/members_bonus.csv)\\" -eq 8 ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 11, '실수 없이 파일을 고치는 순서', '`work.csv` 를 `sed -i` 로 고치기 전후에 하면 좋은 작업입니다. 안전하게 진행하는 순서대로, **앞에서 뒤**로 놓으세요.', '`-i` 는 원래대로 되돌릴 수 없으니 먼저 복사본을 남깁니다. 고친 다음에는 복사본과 비교해서 의도한 줄만 바뀌었는지 보고, 마지막으로 정리합니다.', NULL, NULL, '[]', 'order', '["`cp work.csv work.csv.bak` 으로 복사본(백업)을 만든다", "`sed -i ''s/Seoul/Daejeon/'' work.csv` 로 파일을 직접 고친다", "`diff work.csv.bak work.csv` 로 바뀐 줄만 확인한다", "`rm work.csv.bak` 으로 확인이 끝난 백업을 지운다"]', NULL, '**백업 → 수정 → 비교 → 정리** 순서입니다. `sed -i` 는 파일을 되돌릴 수 없게 덮어쓰므로 백업이 수정보다 먼저여야 합니다. `diff` 는 수정한 뒤에야 비교할 차이가 생기고, 백업은 비교가 끝난 뒤에 지워야 합니다. 비교 전에 지우면 확인할 근거가 사라집니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]'),
  (344, 12, '도구를 이어서 새 CSV 만들기 (sed | cut | sort)', '명단에서 **퇴직하지 않은 사람**만 골라 **`이름,점수`** 두 칸짜리 새 CSV 를 만드세요. 첫 줄은 제목 `name,score` 이고 그 아래는 **점수 높은 순**입니다. 결과는 **`/tmp/lab/summary.csv`** 에 저장합니다. 원본은 그대로 둡니다.', '제목 줄은 `echo` 로 `>` 에 먼저 쓰고, 나머지는 `sed` 로 퇴직 줄 지우기, `cut` 으로 칸 뽑기, `sort` 로 정렬하는 파이프라인을 만들어 `>>` 로 뒤에 덧붙입니다. 칸을 뽑은 뒤에는 점수 칸 번호가 바뀐다는 점에 주의하세요.', 'echo ''name,score'' > /tmp/lab/summary.csv
sed ''/retired/d'' /tmp/lab/members.csv | cut -d, -f2,5 | sort -t, -k2,2nr >> /tmp/lab/summary.csv
cat /tmp/lab/summary.csv

# > 는 덮어쓰기, >> 는 이어 붙이기다. cut 뒤에는 점수가 2번째 칸이 된다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/members.csv <<''CSVEOF''\\n1,kim,dev,Seoul,82,active\\n2,lee,ops,Busan,91,active\\n3,park,qa,Daegu,67,retired\\n4,choi,dev,Seoul,100,active\\n5,jung,ops,Incheon,78,active\\n6,kang,qa,Busan,88,retired\\n7,yoon,dev,Daegu,73,active\\n8,han,ops,Seoul,86,active\\nCSVEOF\\ncat > /tmp/lab/bonus.txt <<''BEOF''\\n5\\n0\\n3\\n10\\n2\\n7\\n0\\n4\\nBEOF\\ncp /tmp/lab/members.csv /tmp/lab/work.csv\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/summary.csv | cut -d\\" \\" -f1)\\" = \\"c06fb133c3debc912a1396dd7d4db740\\" ] ) && ( [ \\"$(wc -l < /tmp/lab/summary.csv)\\" -eq 7 ] ) && ( [ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목과 활성 구성원이 점수 높은 순으로 들어 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/summary.csv | cut -d\\" \\" -f1)\\" = \\"c06fb133c3debc912a1396dd7d4db740\\" ]"]}, {"label": "7 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/summary.csv)\\" -eq 7 ]"]}, {"label": "원본 members.csv 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/members.csv | cut -d\\" \\" -f1)\\" = \\"8e84fce525d4dc7cfcef502f18f042f1\\" ]"]}]', '[{"title": "tr 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/tr.1.html"}, {"title": "cut 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/cut.1.html"}, {"title": "sed 명세 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sed.1p.html"}, {"title": "sort 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/sort.1.html"}, {"title": "paste 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/paste.1.html"}]');
